// List returns one page of records.
func (r *GraphQLEventReportRepository) List(ctx context.Context, in repox.ListInput) ([]*event_reportv1.EventReport, string, error) {
	return r.list(ctx, in)
}

func (r *GraphQLEventReportRepository) list(ctx context.Context, in repox.ListInput, scope ...graphql.Predicate) ([]*event_reportv1.EventReport, string, error) {
	if !in.ShowDeleted {
		scope = append(scope, resourceql.DeleteTime.IsNull(true))
	}
	conds, err := filterx.Parse(in.Filter)
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	conds = append(conds, in.Where...)
	if err := repox.CheckReadMask((*event_reportv1.EventReport)(nil), in.ReadMask); err != nil {
		return nil, "", err
	}
	eng := filterx.Hasura[resourceql.EventreportResource](eventreport.EventReportFilterSpec, r.Svc.Query.Eventreport.Resource).Scope(scope...)
	for f, h := range r.ListOverrides {
		eng.Override(f, h)
	}
	eng.Via("version", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Eventreport.Decimals.List(ctx, decimalsql.List().Where(graphql.And(decimalsql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	eng.Via("general_event_info", func(ctx context.Context, keys []string, where graphql.Predicate) ([]string, error) {
		rows, err := r.Svc.Query.Eventreport.GeneralEventInfos.List(ctx, generaleventinfosql.List().Where(graphql.And(generaleventinfosql.Id.In(keys...), where)))
		ids := make([]string, 0, len(rows))
		for i := range rows {
			ids = append(ids, rows[i].Id)
		}
		return ids, err
	})
	rows, next, err := eng.List(ctx, filterx.ListInput{
		PageSize:  in.PageSize,
		PageToken: in.PageToken,
		OrderBy:   in.OrderBy,
		Filter:    conds,
	})
	if err != nil {
		return nil, "", repox.MapFilterxErr(err)
	}
	items := make([]*event_reportv1.EventReport, 0, len(rows))
	for i := range rows {
		out, err := r.toProto(ctx, &rows[i], in.ReadMask)
		if err != nil {
			return nil, "", err
		}
		repox.Narrow(out, in.ReadMask)
		items = append(items, out)
	}
	return items, next, nil
}

