	existingPB := eventReportFromRow(row)
	if in.GetEtag() != "" && existingPB.GetEtag() != in.GetEtag() {
		return nil, repox.ErrConflict
	}
	var staleVersion string
	staleGeneralEventInfo := repox.Deref(row.GeneralEventInfoId)
