// PurgeEventReport queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeEventReport(name string) {
	if _, err := repox.SplitName(name, "eventReports"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLEventReportRepository{Svc: b.svc}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of this database still names fails
	// the commit with repox.ErrForeignKey: the request is one transaction,
	// and the engine cannot skip one of its mutations.
	keep := queueEventReportPurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/EventReport", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getEventReport)})
}
